1	package registry
2	
3	import (
4		"bytes"
5		"errors"
6		"io"
7		"net/http"
8		"sync/atomic"
9		"time"
10	
11		"github.com/immuta/operations/services/crow/internal/storage"
12		"github.com/labstack/echo/v4"
13	)
14	
15	// gzipMagic is the two-byte header for gzip files.
16	var gzipMagic = []byte{0x1f, 0x8b}
17	
18	type Handler struct {
19		store         storage.Client
20		presignExpiry time.Duration
21		maxUploadSize int64
22		rwPassed      atomic.Bool
23	}
24	
25	func NewHandler(store storage.Client, presignExpiry time.Duration, maxUploadSize int64) *Handler {
26		return &Handler{store: store, presignExpiry: presignExpiry, maxUploadSize: maxUploadSize}
27	}
28	
29	func (h *Handler) Register(e *echo.Echo) {
30		e.GET("/.well-known/terraform.json", h.ServiceDiscovery)
31		e.GET("/v1/modules/:namespace/:name/:provider/versions", h.ListVersions)
32		e.GET("/v1/modules/:namespace/:name/:provider/:version/download", h.Download)
33		e.PUT("/v1/modules/:namespace/:name/:provider/:version", h.Upload)
34		e.GET("/health", h.Health)
35		e.GET("/livez", h.Livez)
36		e.GET("/readyz", h.Readyz)
37	}
38	
39	func (*Handler) Health(c echo.Context) error {
40		return c.NoContent(http.StatusOK)
41	}
42	
43	func (*Handler) Livez(c echo.Context) error {
44		return c.NoContent(http.StatusOK)
45	}
46	
47	func (h *Handler) Readyz(c echo.Context) error {
48		ctx := c.Request().Context()
49	
50		if err := h.store.HeadBucket(ctx); err != nil {
51			c.Logger().Errorf("readyz: %v", err)
52			return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "head bucket check failed"})
53		}
54	
55		if !h.rwPassed.Load() {
56			if err := h.store.CheckReadWrite(ctx); err != nil {
57				c.Logger().Errorf("readyz: %v", err)
58				return c.JSON(http.StatusServiceUnavailable, map[string]string{"error": "read/write check failed"})
59			}
60			h.rwPassed.Store(true)
61		}
62	
63		return c.NoContent(http.StatusOK)
64	}
65	
66	func (*Handler) ServiceDiscovery(c echo.Context) error {
67		return c.JSON(http.StatusOK, map[string]string{
68			"modules.v1": "/v1/modules/",
69		})
70	}
71	
72	type versionEntry struct {
73		Version string `json:"version"`
74	}
75	
76	func (h *Handler) ListVersions(c echo.Context) error {
77		namespace := c.Param("namespace")
78		name := c.Param("name")
79		provider := c.Param("provider")
80	
81		versions, err := h.store.ListVersions(c.Request().Context(), namespace, name, provider)
82		if err != nil {
83			c.Logger().Errorf("failed to list versions: %v", err)
84			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
85		}
86	
87		if len(versions) == 0 {
88			return c.JSON(http.StatusNotFound, map[string]string{"error": "module not found"})
89		}
90	
91		entries := make([]versionEntry, len(versions))
92		for i, v := range versions {
93			entries[i] = versionEntry{Version: v}
94		}
95	
96		resp := map[string]any{
97			"modules": []map[string]any{
98				{"versions": entries},
99			},
100		}
101	
102		return c.JSON(http.StatusOK, resp)
103	}
104	
105	func (h *Handler) Download(c echo.Context) error {
106		namespace := c.Param("namespace")
107		name := c.Param("name")
108		provider := c.Param("provider")
109		version := c.Param("version")
110	
111		ctx := c.Request().Context()
112	
113		exists, err := h.store.HeadModule(ctx, namespace, name, provider, version)
114		if err != nil {
115			c.Logger().Errorf("failed to check module existence: %v", err)
116			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
117		}
118	
119		if !exists {
120			return c.JSON(http.StatusNotFound, map[string]string{"error": "module version not found"})
121		}
122	
123		url, err := h.store.PresignGetModule(ctx, namespace, name, provider, version, h.presignExpiry)
124		if err != nil {
125			c.Logger().Errorf("failed to generate presigned URL: %v", err)
126			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
127		}
128	
129		c.Response().Header().Set("X-Terraform-Get", url)
130		return c.NoContent(http.StatusNoContent)
131	}
132	
133	// Upload stores a module archive in S3. The existence check and write are not
134	// atomic (TOCTOU): a concurrent upload between HeadModule and PutModule could
135	// result in a silent overwrite because S3 PutObject is last-write-wins.
136	// Conditional writes (If-None-Match) are not universally supported across
137	// S3-compatible backends, so we accept this trade-off.
138	func (h *Handler) Upload(c echo.Context) error {
139		namespace := c.Param("namespace")
140		name := c.Param("name")
141		provider := c.Param("provider")
142		version := c.Param("version")
143	
144		ctx := c.Request().Context()
145	
146		exists, err := h.store.HeadModule(ctx, namespace, name, provider, version)
147		if err != nil {
148			c.Logger().Errorf("failed to check module existence: %v", err)
149			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
150		}
151		if exists {
152			return c.JSON(http.StatusConflict, map[string]string{"error": "module version already exists"})
153		}
154	
155		body := http.MaxBytesReader(c.Response(), c.Request().Body, h.maxUploadSize)
156		defer body.Close()
157	
158		header := make([]byte, len(gzipMagic))
159		if _, err := io.ReadFull(body, header); err != nil {
160			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is too small or empty"})
161		}
162		if header[0] != gzipMagic[0] || header[1] != gzipMagic[1] {
163			return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body is not a valid gzip archive"})
164		}
165	
166		// Buffer the full body so S3 PutObject gets a seekable reader, which the
167		// AWS SDK requires for checksum computation over non-TLS connections.
168		// This is bounded by MaxBytesReader so memory usage is capped at maxUploadSize.
169		rest, err := io.ReadAll(body)
170		if err != nil {
171			var maxBytesErr *http.MaxBytesError
172			if errors.As(err, &maxBytesErr) {
173				return c.JSON(http.StatusBadRequest, map[string]string{"error": "request body exceeds maximum upload size"})
174			}
175			return c.JSON(http.StatusBadRequest, map[string]string{"error": "failed to read request body"})
176		}
177		full := append(header, rest...)
178		if err := h.store.PutModule(ctx, namespace, name, provider, version, bytes.NewReader(full)); err != nil {
179			c.Logger().Errorf("failed to store module: %v", err)
180			return c.JSON(http.StatusInternalServerError, map[string]string{"error": "internal server error"})
181		}
182	
183		return c.NoContent(http.StatusCreated)
184	}
