1	package storage
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9		"time"
10	
11		"github.com/aws/aws-sdk-go-v2/aws"
12		"github.com/aws/aws-sdk-go-v2/service/s3"
13		"github.com/aws/aws-sdk-go-v2/service/s3/types"
14	)
15	
16	type S3Client struct {
17		client     *s3.Client
18		presigner  *s3.PresignClient
19		bucketName string
20	}
21	
22	func NewS3Client(awsCfg aws.Config, bucketName string, optFns ...func(*s3.Options)) *S3Client {
23		client := s3.NewFromConfig(awsCfg, optFns...)
24		return &S3Client{
25			client:     client,
26			presigner:  s3.NewPresignClient(client),
27			bucketName: bucketName,
28		}
29	}
30	
31	// NewS3ClientWithPresignEndpoint creates an S3Client that uses a separate
32	// endpoint for generating presigned URLs. This is needed when the S3 backend
33	// is reachable internally at one address (e.g. http://rustfs:9000) but
34	// clients need presigned URLs pointing to an external address (e.g.
35	// http://localhost:9000).
36	func NewS3ClientWithPresignEndpoint(awsCfg aws.Config, bucketName, presignEndpoint string, optFns ...func(*s3.Options)) *S3Client {
37		client := s3.NewFromConfig(awsCfg, optFns...)
38		presignClient := s3.NewFromConfig(awsCfg, append(optFns, func(o *s3.Options) {
39			o.BaseEndpoint = &presignEndpoint
40		})...)
41		return &S3Client{
42			client:     client,
43			presigner:  s3.NewPresignClient(presignClient),
44			bucketName: bucketName,
45		}
46	}
47	
48	func objectKey(namespace, name, provider, version string) string {
49		return fmt.Sprintf("%s/%s/%s/%s.tar.gz", namespace, name, provider, version)
50	}
51	
52	func prefix(namespace, name, provider string) string {
53		return fmt.Sprintf("%s/%s/%s/", namespace, name, provider)
54	}
55	
56	func extractVersion(key, pfx string) (string, bool) {
57		if !strings.HasPrefix(key, pfx) {
58			return "", false
59		}
60		rest := strings.TrimPrefix(key, pfx)
61		if !strings.HasSuffix(rest, ".tar.gz") {
62			return "", false
63		}
64		version := strings.TrimSuffix(rest, ".tar.gz")
65		if version == "" {
66			return "", false
67		}
68		return version, true
69	}
70	
71	func (s *S3Client) ListVersions(ctx context.Context, namespace, name, provider string) ([]string, error) {
72		pfx := prefix(namespace, name, provider)
73		input := &s3.ListObjectsV2Input{
74			Bucket: &s.bucketName,
75			Prefix: &pfx,
76		}
77	
78		var versions []string
79		paginator := s3.NewListObjectsV2Paginator(s.client, input)
80		for paginator.HasMorePages() {
81			output, err := paginator.NextPage(ctx)
82			if err != nil {
83				return nil, fmt.Errorf("listing objects: %w", err)
84			}
85			for _, obj := range output.Contents {
86				if obj.Key == nil {
87					return nil, errors.New("listing objects: object key is nil")
88				}
89				if v, ok := extractVersion(*obj.Key, pfx); ok {
90					versions = append(versions, v)
91				}
92			}
93		}
94	
95		return versions, nil
96	}
97	
98	func (s *S3Client) HeadModule(ctx context.Context, namespace, name, provider, version string) (bool, error) {
99		key := objectKey(namespace, name, provider, version)
100		_, err := s.client.HeadObject(ctx, &s3.HeadObjectInput{
101			Bucket: &s.bucketName,
102			Key:    &key,
103		})
104		if err != nil {
105			var notFound *types.NotFound
106			var noSuchKey *types.NoSuchKey
107			if errors.As(err, &notFound) || errors.As(err, &noSuchKey) {
108				return false, nil
109			}
110			return false, fmt.Errorf("head object: %w", err)
111		}
112		return true, nil
113	}
114	
115	func (s *S3Client) PutModule(ctx context.Context, namespace, name, provider, version string, body io.Reader) error {
116		key := objectKey(namespace, name, provider, version)
117		contentType := "application/gzip"
118		_, err := s.client.PutObject(ctx, &s3.PutObjectInput{
119			Bucket:      &s.bucketName,
120			Key:         &key,
121			Body:        body,
122			ContentType: &contentType,
123		})
124		if err != nil {
125			return fmt.Errorf("put object: %w", err)
126		}
127		return nil
128	}
129	
130	func (s *S3Client) PresignGetModule(ctx context.Context, namespace, name, provider, version string, expiry time.Duration) (string, error) {
131		key := objectKey(namespace, name, provider, version)
132		req, err := s.presigner.PresignGetObject(ctx, &s3.GetObjectInput{
133			Bucket: &s.bucketName,
134			Key:    &key,
135		}, s3.WithPresignExpires(expiry))
136		if err != nil {
137			return "", fmt.Errorf("presigning URL: %w", err)
138		}
139		return req.URL, nil
140	}
141	
142	const readyzKey = ".readyz"
143	
144	func (s *S3Client) HeadBucket(ctx context.Context) error {
145		_, err := s.client.HeadBucket(ctx, &s3.HeadBucketInput{
146			Bucket: &s.bucketName,
147		})
148		if err != nil {
149			return fmt.Errorf("head bucket: %w", err)
150		}
151		return nil
152	}
153	
154	func (s *S3Client) CheckReadWrite(ctx context.Context) error {
155		body := strings.NewReader(time.Now().UTC().Format(time.RFC3339))
156		_, err := s.client.PutObject(ctx, &s3.PutObjectInput{
157			Bucket: &s.bucketName,
158			Key:    aws.String(readyzKey),
159			Body:   body,
160		})
161		if err != nil {
162			return fmt.Errorf("readyz put object: %w", err)
163		}
164	
165		_, err = s.client.HeadObject(ctx, &s3.HeadObjectInput{
166			Bucket: &s.bucketName,
167			Key:    aws.String(readyzKey),
168		})
169		if err != nil {
170			return fmt.Errorf("readyz head object: %w", err)
171		}
172	
173		return nil
174	}
