14	func TestPrefix(t *testing.T) {
15		p := prefix("hashicorp", "consul", "aws")
16		assert.Equal(t, "hashicorp/consul/aws/", p)
17	}
18	
19	func TestExtractVersion(t *testing.T) {
20		tests := []struct {
21			key      string
22			prefix   string
23			expected string
24			valid    bool
25		}{
26			{"hashicorp/consul/aws/1.0.0.tar.gz", "hashicorp/consul/aws/", "1.0.0", true},
27			{"hashicorp/consul/aws/2.3.1.tar.gz", "hashicorp/consul/aws/", "2.3.1", true},
28			{"hashicorp/consul/aws/readme.md", "hashicorp/consul/aws/", "", false},
29			{"hashicorp/consul/aws/", "hashicorp/consul/aws/", "", false},
30		}
31	
32		for _, tt := range tests {
33			t.Run(tt.key, func(t *testing.T) {
34				v, ok := extractVersion(tt.key, tt.prefix)
35				assert.Equal(t, tt.valid, ok)
36				if ok {
37					assert.Equal(t, tt.expected, v)
38				}
39			})
40		}
41	}
